 "content": "def transform(grid):
    # Identify monochromatic rectangular outlines by their bounding boxes.
    h, w = len(grid), len(grid[0])
    boxes = []
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        # Objects are the outlined rectangles; interior pattern cells may also be same color.
        if all(grid[r0][c] == color for c in range(c0, c1 + 1)) and all(grid[r1][c] == color for c in range(c0, c1 + 1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1)):
            boxes.append((color, r0, r1, c0, c1))
    # Select the framed box containing a non-empty interior pattern as the source.
    patterned = []
    for color, r0, r1, c0, c1 in boxes:
        inside = [[grid[r][c] for c in range(c0 + 1, c1)] for r in range(r0 + 1, r1)]
        if any(v != 0 for row in inside for v in row):
            patterned.append((color, r0, r1, c0, c1, inside))
    if not patterned:
        return [row[:] for row in grid]
    src_color, sr0, sr1, sc0, sc1, pat = patterned[0]
    sh, sw = len(pat), len(pat[0]) if pat else 0
    out = [row[:] for row in grid]
    for color, r0, r1, c0, c1 in boxes:
        if color == src_color:
            continue
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        # A frame that cannot accept the complete pattern is removed; matching frames receive it.
        if ih != sh or iw != sw:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if out[r][c] == color:
                        out[r][c] = 0
        else:
            for i in range(ih):
                for j in range(iw):
                    if pat[i][j] != 0:
                        out[r0 + 1 + i][c0 + 1 + j] = color
    return out

if __name__ == '__main__':
    pass
